import{_ as o,H as r,c as s,b as i,a2 as a,K as n}from"./chunks/framework.BEqfOpL-.js";const g=JSON.parse(`{"title":"Show Visibility","description":"Show Visibility reveals where your podcast appears when people search for keywords on major platforms (Apple Podcasts, Spotify, Amazon Music, YouTube Music). Each number shows your podcast's ranking position for that keyword - lower numbers indicate better rankings.","frontmatter":{},"headers":[],"relativePath":"features/show-visibility.md","filePath":"features/show-visibility.md"}`),l={name:"features/show-visibility.md"};function h(d,e,c,p,u,y){const t=r("HelpWalkthrough");return i(),s("div",null,[e[0]||(e[0]=a('<h1 id="show-visibility" tabindex="-1">Show Visibility <a class="header-anchor" href="#show-visibility" aria-label="Permalink to &quot;Show Visibility&quot;">​</a></h1><h2 id="track-your-podcast-s-organic-search-performance" tabindex="-1">Track Your Podcast&#39;s Organic Search Performance <a class="header-anchor" href="#track-your-podcast-s-organic-search-performance" aria-label="Permalink to &quot;Track Your Podcast&#39;s Organic Search Performance&quot;">​</a></h2><p>Show Visibility reveals where your podcast appears when people search for keywords on major platforms (Apple Podcasts, Spotify, Amazon Music, YouTube Music). Each number shows your podcast&#39;s ranking position for that keyword - lower numbers indicate better rankings.</p><p>In the app, this is the <strong>show view of the Search Appearances tab</strong> (in <strong>Get found → Search Visibility</strong>; older guides called it Organic Visibility). The same tab also has an episode view—see <a href="/features/episode-visibility.html">Episode Visibility</a>—but this article covers the show-level view.</p><p>Use this view to find relevant terms your show already ranks for, then choose which ones to monitor. A position indicates observed search visibility; it does not measure clicks or listening.</p><h2 id="find-a-term-and-start-tracking-it" tabindex="-1">Find a term and start tracking it <a class="header-anchor" href="#find-a-term-and-start-tracking-it" aria-label="Permalink to &quot;Find a term and start tracking it&quot;">​</a></h2><ol><li>Use the <strong>Search volume</strong> chips to include the volume levels you want to inspect.</li><li>Select a platform header to sort its positions. Lower numbers mean higher positions.</li><li>Find a phrase relevant to your show and click <strong>Track</strong>. It uses one of your tracked-keyword slots.</li><li>Open <strong>Strategy</strong> to find the saved term and choose a purpose with <strong>Assign</strong>.</li></ol>',7)),n(t,{src:"/walkthroughs/organic-track.webp",poster:"/images/show_visibility.webp",alt:"Filter and sort organic rankings, track a relevant phrase, and find it in Keyword Strategy",duration:27700,autoplay:"",loop:"",sample:""}),e[1]||(e[1]=a('<p>Tracking alone does not assign a Show or Episode target. Use <strong>Tracker</strong> to follow the phrase&#39;s history after tracking it.</p><h2 id="read-the-page" tabindex="-1">Read the page <a class="header-anchor" href="#read-the-page" aria-label="Permalink to &quot;Read the page&quot;">​</a></h2><p>The summary cards count qualifying <strong>Top 50</strong> keywords across platforms, with separate Apple Podcasts and Spotify counts and a combined Amazon Music / YouTube Music count. The table below presents a selection of those results. Volume filters change the loaded rows, not the headline totals.</p><p>The six-step <strong>Search volume</strong> meter describes a monthly search range. Hover or focus it for the range; a clock means the term has not been measured yet. See <a href="/features/keyword-strategy.html#read-keyword-measurements">Keyword Strategy</a> for the six levels. Relevance matters alongside volume: a niche phrase can be a useful target.</p><h2 id="why-some-keywords-don-t-appear-in-show-visibility" tabindex="-1">Why Some Keywords Don&#39;t Appear in Show Visibility <a class="header-anchor" href="#why-some-keywords-don-t-appear-in-show-visibility" aria-label="Permalink to &quot;Why Some Keywords Don&#39;t Appear in Show Visibility&quot;">​</a></h2><p>Show Visibility presents a selection of observed top-50 rankings. A missing keyword does not prove that your show has no ranking for it. Check these possibilities:</p><ol><li><p><strong>Your podcast doesn&#39;t rank in the top 50 for that keyword</strong>: Show Visibility only shows keywords where your podcast currently ranks within the top 50 on at least one platform. Results outside the top 50 are not included.</p></li><li><p><strong>The keyword hasn&#39;t been checked yet</strong>: some niche or new phrases may not have observed search results yet.</p></li><li><p><strong>The available selection or your filters exclude it</strong>: this discovery table does not list every observed keyword. Clear the volume filter, then use Tracker to inspect a specific tracked phrase.</p></li></ol><p><strong>To monitor a specific phrase</strong>:</p><ol><li>Add it in <a href="/features/keyword-strategy.html">Keyword Strategy</a> if you are not already tracking it.</li><li>Open it in <a href="/features/keyword-tracker.html">Keyword Tracker</a> to inspect its available rankings, even if it is absent from Show Visibility.</li></ol><h2 id="plan-restrictions" tabindex="-1">Plan Restrictions <a class="header-anchor" href="#plan-restrictions" aria-label="Permalink to &quot;Plan Restrictions&quot;">​</a></h2><h3 id="free-plan" tabindex="-1">Free Plan <a class="header-anchor" href="#free-plan" aria-label="Permalink to &quot;Free Plan&quot;">​</a></h3><p>The three best-ranked terms in the available results are revealed. Other rows retain positions and volume but hide the keyword name behind <strong>Upgrade to See Keyword</strong>. All volume filters remain available, and you can track revealed terms within your allowance. Upgrading reveals the names in the available selection.</p><h3 id="paid-plans" tabindex="-1">Paid Plans <a class="header-anchor" href="#paid-plans" aria-label="Permalink to &quot;Paid Plans&quot;">​</a></h3><ul><li><strong>Full Keyword Names</strong>: The available selection is shown in clear, with search volume and platform rankings</li><li><strong>Higher Tracking Allowance</strong>: Every plan has a cap on total tracked keywords — Free 5, Podcaster 100, Producer 500, Agency 50,000 (shared across all podcasts in your account). Adding a keyword beyond your plan&#39;s cap prompts an upgrade, so untrack keywords you no longer follow to free up slots.</li></ul><p>Assign tracked terms to <strong>Show</strong> for <a href="/features/show-optimization.html">Show optimization</a>, or to an episode for its checks in <a href="/features/planner.html">Planner</a>.</p>',15))])}const w=o(l,[["render",h]]);export{g as __pageData,w as default};
